def followup_view(inputs, prior):
    packet=inputs.get('eighth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('period packet changed')
    if prior is None or prior['counts']['after']!=74 or packet['prior_digest']!=digest(prior):raise ValueError('period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=14 or len(packet['sources'])!=14 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid] or not s['protected_gate_passed']:raise ValueError('period source binding changed')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)} or len(s['page_hashes'])!=s['pages']:raise ValueError('period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('period page changed')
    for metric in H1_METRICS:
        actual=((D(metric['current_yuan'])-D(metric['prior_yuan']))/abs(D(metric['prior_yuan']))*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if actual!=D(metric['reported_pct']):raise ValueError('period H1 arithmetic changed')
